<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesListRef;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesUidVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesAudienceVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesVersionVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\TrustedClientAllowedAudiencesItem;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientAllowedAudiencesAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientAllowedAudiencesAccessor trait.
 *
 * Covers null default, string/VO assignment via withAllowedAudiences,
 * getAllowedAudiences/allowedAudiences accessors, and isAllowedAudiencesChanged with/without original.
 */
class TrustedClientAllowedAudiencesAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAllowedAudiences creates a new instance with the AllowedAudiences set
     * from a string value, and getAllowedAudiences returns the primitive string.
     */
    public function testWithAllowedAudiencesFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedAudiencesAccessorUnitTest();

        // Act
        $result = $holder->withAllowedAudiences(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )), $result->getAllowedAudiences());
    }
    /**
     * Asserts that withallowedAudiences has access to the value object
     * from a string value, and getAllowedAudiences returns the primitive string.
     */
    public function testWithAllowedAudiencesFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedAudiencesAccessorUnitTest();

        // Act
        $result = $holder->withAllowedAudiences(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )), $result->allowedAudiences()->value());
    }
    public function testChangedAllowedAudiences(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientAllowedAudiencesAccessorUnitTest()->withAllowedAudiences(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )));
        $original = $holder->withAllowedAudiences(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )));
        $same = $holder->withAllowedAudiences(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('one'),
            TrustedClientAllowedAudiencesAudienceVO::from('one'),
            TrustedClientAllowedAudiencesVersionVO::from(1)
        )));
        $modified = $holder->withAllowedAudiences(new TrustedClientAllowedAudiencesListRef(new TrustedClientAllowedAudiencesItem(
            TrustedClientAllowedAudiencesUidVO::from('other'),
            TrustedClientAllowedAudiencesAudienceVO::from('other'),
            TrustedClientAllowedAudiencesVersionVO::from(2)
        )));

        // Act
        $withSame = $original->isAllowedAudiencesChanged($same);
        $withDiferent = $original->isAllowedAudiencesChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientAllowedAudiencesAccessorUnitTest
{
    use TrustedClientAllowedAudiencesAccessor;
}
